    def test_checker_rejects_corrupted_null_last(self):
        scenario = get_scenario('late_gap_ready_peer')
        sim = simulate('recourse', scenario)
        self.assertTrue(check_trace(sim['events'], scenario, 'recourse')['ok'])
        null_w = [e for e in sim['events'] if e['type'] == 'W' and e.get('mode') == 'null']
